import{_ as i,C as a,c as e,o,j as l,G as t,b as r,a0 as n,a as s,w as c,a1 as u}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Comunicazione di squadra","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/team-player/communication.md","filePath":"it/education/team-player/communication.md"}');const p=i({name:"it/education/team-player/communication.md"},[["render",function(i,d,p,m,h,g){const q=a("AdBanner"),b=a("Mermaid"),f=a("AdInArticle");return o(),e("div",null,[d[1]||(d[1]=l("h1",{id:"comunicazione-di-squadra",tabindex:"-1"},[s("Comunicazione di squadra "),l("a",{class:"header-anchor",href:"#comunicazione-di-squadra","aria-label":'Permalink to "Comunicazione di squadra"'},"​")],-1)),t(q),d[2]||(d[2]=l("p",null,"Una comunicazione efficace è ciò che trasforma un gruppo di individui in una squadra. Nel gioco delle bocce, dove la strategia cambia costantemente e la pressione è alta, il modo in cui si comunica può determinare il risultato.",-1)),d[3]||(d[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"La grande idea"),l("p",null,[l("strong",null,"La comunicazione è ciò che trasforma gli individui in una squadra."),s(" Una comunicazione chiara, specifica e di supporto sotto pressione distingue i buoni team da quelli eccellenti.")])],-1)),d[4]||(d[4]=l("h2",{id:"il-ciclo-della-comunicazione",tabindex:"-1"},[s("Il ciclo della comunicazione "),l("a",{class:"header-anchor",href:"#il-ciclo-della-comunicazione","aria-label":'Permalink to "Il ciclo della comunicazione"'},"​")],-1)),d[5]||(d[5]=l("p",null,"Una buona comunicazione di squadra segue un ciclo:",-1)),(o(),r(u,null,{default:c(()=>[t(b,{id:"mermaid-19",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BOsservare%5D%20--%3E%20B%5BCondividere%5D%0A%20%20%20%20B%20--%3E%20C%5BDiscutere%5D%0A%20%20%20%20C%20--%3E%20D%5BDecidere%5D%0A%20%20%20%20D%20--%3E%20E%5BEseguire%5D%0A%20%20%20%20E%20--%3E%20F%5BRevisione%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:c(()=>[...d[0]||(d[0]=[s(" Loading... ",-1)])]),_:1})),d[6]||(d[6]=n('<table tabindex="0"><thead><tr><th>Fare un passo</th><th>Azione</th><th>Esempio</th></tr></thead><tbody><tr><td><strong>Osservare</strong></td><td>Nota cosa sta succedendo</td><td>Terreno, posizioni, avversari</td></tr><tr><td><strong>Condividere</strong></td><td>Racconta ai compagni di squadra cosa vedi</td><td>&quot;Il terreno pende lì&quot;</td></tr><tr><td><strong>Discutere</strong></td><td>Scambio di prospettive</td><td>&quot;Devo bloccare o andare a segno?&quot;</td></tr><tr><td><strong>Decidere</strong></td><td>Concordare l&#39;approccio</td><td>&quot;Proviamo il lob alto&quot;</td></tr><tr><td><strong>Eseguire</strong></td><td>Fallo con impegno</td><td>Concentrazione completa sul lancio</td></tr><tr><td><strong>Revisione</strong></td><td>Impara dai risultati</td><td>&quot;Ha funzionato bene&quot; oppure &quot;La prossima volta...&quot;</td></tr></tbody></table><h2 id="quando-comunicare" tabindex="-1">Quando comunicare <a class="header-anchor" href="#quando-comunicare" aria-label="Permalink to &quot;Quando comunicare&quot;">​</a></h2><h3 id="prima-di-ogni-fine" tabindex="-1">Prima di ogni fine <a class="header-anchor" href="#prima-di-ogni-fine" aria-label="Permalink to &quot;Prima di ogni fine&quot;">​</a></h3><ul><li>Valutare insieme il terreno</li><li>Discutere l&#39;approccio generale</li><li>Chiarire chi lancia e quando</li><li>Imposta il tono (calmo, concentrato)</li></ul><h3 id="durante-la-fine" tabindex="-1">Durante la fine <a class="header-anchor" href="#durante-la-fine" aria-label="Permalink to &quot;Durante la fine&quot;">​</a></h3><ul><li>Condividi le osservazioni (&quot;Il terreno è rimasto lì in pendenza&quot;)</li><li>Coordinare la strategia (&quot;Devo provare a bloccare o andare al punto?&quot;)</li><li>Offri supporto (&quot;Prenditi il tuo tempo, ce la puoi fare&quot;)</li><li>Adattare i piani in base ai cambiamenti della situazione</li></ul><h3 id="tra-le-estremita" tabindex="-1">Tra le estremità <a class="header-anchor" href="#tra-le-estremita" aria-label="Permalink to &quot;Tra le estremità&quot;">​</a></h3><ul><li>Breve debriefing (cosa ha funzionato e cosa no)</li><li>Ripristina mentalmente</li><li>Preparati per la prossima fine</li><li>Rimani connesso come una squadra</li></ul><h3 id="dopo-la-partita" tabindex="-1">Dopo la partita <a class="header-anchor" href="#dopo-la-partita" aria-label="Permalink to &quot;Dopo la partita&quot;">​</a></h3><ul><li>Debriefing completo (quando appropriato)</li><li>Riconosci i contributi</li><li>Identificare gli apprendimenti</li><li>Mantenere la relazione</li></ul><h2 id="come-comunicare" tabindex="-1">Come comunicare <a class="header-anchor" href="#come-comunicare" aria-label="Permalink to &quot;Come comunicare&quot;">​</a></h2><h3 id="sii-chiaro-e-specifico" tabindex="-1">Sii chiaro e specifico <a class="header-anchor" href="#sii-chiaro-e-specifico" aria-label="Permalink to &quot;Sii chiaro e specifico&quot;">​</a></h3><p><strong>Vago:</strong> &quot;Cerca di avvicinarti&quot; <strong>Chiaro:</strong> &quot;Mira al lato sinistro del cric, a circa 20 cm di distanza&quot;</p><p><strong>Vago:</strong> &quot;Bel tentativo&quot; <strong>Clear:</strong> &quot;Buon peso, solo un po&#39; a sinistra della linea&quot;</p><h3 id="sii-costruttivo" tabindex="-1">Sii costruttivo <a class="header-anchor" href="#sii-costruttivo" aria-label="Permalink to &quot;Sii costruttivo&quot;">​</a></h3><p>Concentratevi sulle soluzioni, non sui problemi:</p><p><strong>Incentrato sul problema:</strong> &quot;Continui a sbagliare direzione a destra&quot; <strong>Incentrato sulla soluzione:</strong> &quot;Forse potresti provare a mirare un po&#39; più a sinistra per compensare?&quot;</p><h3 id="sii-di-supporto" tabindex="-1">Sii di supporto <a class="header-anchor" href="#sii-di-supporto" aria-label="Permalink to &quot;Sii di supporto&quot;">​</a></h3><p>Il tono è importante tanto quanto le parole:</p><ul><li>Mantieni la calma, anche quando sei frustrato</li><li>Usa un linguaggio del corpo incoraggiante</li><li>Riconoscere lo sforzo, non solo i risultati</li><li>Costruisci, non demolire</li></ul><h3 id="ascoltare-attivamente" tabindex="-1">Ascoltare attivamente <a class="header-anchor" href="#ascoltare-attivamente" aria-label="Permalink to &quot;Ascoltare attivamente&quot;">​</a></h3><p>La comunicazione è bidirezionale:</p><ul><li>Prestare la massima attenzione quando parlano i compagni di squadra</li><li>Fai domande di chiarimento</li><li>Riconosci ciò che hai sentito</li><li>Non interrompere o ignorare</li></ul>',23)),t(f),d[7]||(d[7]=n('<h2 id="sfide-di-comunicazione" tabindex="-1">Sfide di comunicazione <a class="header-anchor" href="#sfide-di-comunicazione" aria-label="Permalink to &quot;Sfide di comunicazione&quot;">​</a></h2><h3 id="disaccordo-sulla-strategia" tabindex="-1">Disaccordo sulla strategia <a class="header-anchor" href="#disaccordo-sulla-strategia" aria-label="Permalink to &quot;Disaccordo sulla strategia&quot;">​</a></h3><p><strong>Approccio scadente:</strong></p><ul><li>Insisti sulla tua strada</li><li>Mettiti sulla difensiva</li><li>Cedere con risentimento</li><li>Discutere durante il gioco</li></ul><p><strong>Approccio migliore:</strong></p><ol><li>Condividi chiaramente la tua prospettiva</li><li>Ascoltate attentamente i loro</li><li>Discutere brevemente i pro e i contro</li><li>Decidere insieme (o delegare al leader designato)</li><li>Impegnarsi pienamente nella decisione</li><li>Recensione dopo la partita</li></ol><h3 id="dopo-l-39-errore-di-un-compagno-di-squadra" tabindex="-1">Dopo l&#39;errore di un compagno di squadra <a class="header-anchor" href="#dopo-l-39-errore-di-un-compagno-di-squadra" aria-label="Permalink to &quot;Dopo l&amp;#39;errore di un compagno di squadra&quot;">​</a></h3><p><strong>Di cosa hanno bisogno:</strong></p><ul><li>Riconoscimento rapido</li><li>Permesso di andare avanti</li><li>La sicurezza che ti fidi ancora di loro</li><li>Concentrati sul prossimo lancio</li></ul><p><strong>Cosa dire:</strong></p><ul><li>&quot;Nessun problema, il prossimo&quot;</li><li>&quot;Brutta sorpresa, ora tocca a te&quot;</li><li>&quot;Siamo ancora dentro&quot;</li><li><em>A volte basta un cenno o una pacca</em></li></ul><p><strong>Cosa NON dire:</strong></p><ul><li>Niente (il silenzio sembra un giudizio)</li><li>&quot;Va bene&quot; (può sembrare sprezzante)</li><li>Tutto ciò che è andato storto (non ora)</li><li>Frustrazione visibile (il linguaggio del corpo conta)</li></ul><h3 id="quando-commetti-un-errore" tabindex="-1">Quando commetti un errore <a class="header-anchor" href="#quando-commetti-un-errore" aria-label="Permalink to &quot;Quando commetti un errore&quot;">​</a></h3><p><strong>Cosa fare:</strong></p><ul><li>Breve riconoscimento (&quot;Colpa mia&quot;)</li><li>Non scusarti troppo</li><li>Non cercare scuse</li><li>Ripristina e concentrati sul prossimo lancio</li><li>Fidati dei tuoi compagni di squadra per farti supportare</li></ul><h3 id="tensione-nella-squadra" tabindex="-1">Tensione nella squadra <a class="header-anchor" href="#tensione-nella-squadra" aria-label="Permalink to &quot;Tensione nella squadra&quot;">​</a></h3><p>Se durante una partita la tensione aumenta:</p><ol><li>Riconosci che sta accadendo</li><li>Fai un respiro prima di rispondere</li><li>Concentrati sul gioco, non sul conflitto</li><li>Affrontalo correttamente dopo la partita</li><li>Non lasciare che influenzi il tuo gioco</li></ol><h2 id="comunicazione-non-verbale" tabindex="-1">Comunicazione non verbale <a class="header-anchor" href="#comunicazione-non-verbale" aria-label="Permalink to &quot;Comunicazione non verbale&quot;">​</a></h2><p>Gran parte della comunicazione di squadra è non verbale:</p><h3 id="segnali-positivi" tabindex="-1">Segnali positivi <a class="header-anchor" href="#segnali-positivi" aria-label="Permalink to &quot;Segnali positivi&quot;">​</a></h3><ul><li>Contatto visivo</li><li>Annuendo</li><li>Pollice su</li><li>Postura rilassata</li><li>Muovendosi verso i compagni di squadra</li><li>Sorridere (quando appropriato)</li></ul><h3 id="segnali-negativi-da-evitare" tabindex="-1">Segnali negativi (da evitare) <a class="header-anchor" href="#segnali-negativi-da-evitare" aria-label="Permalink to &quot;Segnali negativi (da evitare)&quot;">​</a></h3><ul><li>Occhi al cielo</li><li>voltarsi</li><li>braccia incrociate</li><li>Sospirando</li><li>Scuotendo la testa</li><li>Linguaggio del corpo teso</li></ul><p><strong>Ricorda:</strong> I tuoi compagni di squadra vedono tutto. Il tuo linguaggio del corpo influenza la loro sicurezza e le loro prestazioni.</p><h2 id="costruire-abitudini-comunicative" tabindex="-1">Costruire abitudini comunicative <a class="header-anchor" href="#costruire-abitudini-comunicative" aria-label="Permalink to &quot;Costruire abitudini comunicative&quot;">​</a></h2><h3 id="praticare-la-comunicazione" tabindex="-1">Praticare la comunicazione <a class="header-anchor" href="#praticare-la-comunicazione" aria-label="Permalink to &quot;Praticare la comunicazione&quot;">​</a></h3><p>Non aspettare che sia la concorrenza a comunicare:</p><ul><li>Praticare discussioni strategiche durante la formazione</li><li>Fornitevi feedback regolarmente</li><li>Sviluppa il linguaggio del tuo team</li><li>Costruisci conforto con una conversazione onesta</li></ul><h3 id="sviluppare-segnali-di-squadra" tabindex="-1">Sviluppare segnali di squadra <a class="header-anchor" href="#sviluppare-segnali-di-squadra" aria-label="Permalink to &quot;Sviluppare segnali di squadra&quot;">​</a></h3><p>Alcuni team sviluppano delle abbreviazioni:</p><ul><li>Segnali manuali per la strategia</li><li>Parole in codice per le situazioni</li><li>Frasi rapide con significato condiviso</li></ul><h3 id="check-in-regolari" tabindex="-1">Check-in regolari <a class="header-anchor" href="#check-in-regolari" aria-label="Permalink to &quot;Check-in regolari&quot;">​</a></h3><p>Fuori dai giochi:</p><ul><li>Come stiamo lavorando insieme?</li><li>Cosa sta andando bene?</li><li>Cosa potrebbe esserci di meglio?</li><li>Ci sono problemi da risolvere?</li></ul><h2 id="il-ruolo-del-capitano" tabindex="-1">Il ruolo del capitano <a class="header-anchor" href="#il-ruolo-del-capitano" aria-label="Permalink to &quot;Il ruolo del capitano&quot;">​</a></h2><p>Se il tuo team ha un leader designato:</p><p><strong>Responsabilità del capitano:</strong></p><ul><li>Decisione finale quando la squadra non è d&#39;accordo</li><li>Dare il tono e l&#39;energia</li><li>Gestire le dinamiche di squadra</li><li>Mantenere la concentrazione durante la pressione</li></ul><p><strong>Tutti gli altri:</strong></p><ul><li>Condividi la tua prospettiva</li><li>Sostieni la decisione una volta presa</li><li>Aiuta a mantenere l&#39;energia del team</li><li>Assumiti la responsabilità del tuo ruolo</li></ul><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>I grandi team parlano tra loro, non l&#39;uno dell&#39;altro. Comunicano con onestà, rispetto e un impegno condiviso per il successo.</p></blockquote><p>Esercitati a comunicare come ti eserciti a lanciare. È un&#39;abilità che migliora con l&#39;attenzione.</p>',45)),t(q)])}]]);export{d as __pageData,p as default};
